mapper.select:
SELECT *
FROM TBL_FINANCIAL_LEASE
WHERE DELETE_FLAG = 0

    AND LEASE_TYPE = #{leasingType}


    AND LEASE_STATUS = #{applicationStatus}


    AND COMPANY_ID = #{companyId}


    AND CURRENCY_CODE = #{currencyCode}


    AND LESSOR_NAME LIKE CONCAT('%', #{leasingCompany}, '%')


    AND LEASE_NO LIKE CONCAT('%', #{leaseNo}, '%')


    AND START_DATE >= #{startDate}


    AND END_DATE <= #{endDate}

ORDER BY CREATED_TIME DESC

SELECT TO_CHAR(START_DATE, 'YYYY-MM') AS month, COUNT(*) AS applicationCount, COALESCE(SUM(LEASE_AMOUNT), 0) AS totalAmount FROM TBL_FINANCIAL_LEASE WHERE DELETE_FLAG = 0
AND START_DATE >= #{startDate}
AND START_DATE <= #{endDate}
GROUP BY TO_CHAR(START_DATE, 'YYYY-MM') ORDER BY month ASC
